def choose_move(observation):
    w = observation['grid_width']
    h = observation['grid_height']
    px, py = observation['self_position']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    def in_bounds(x,y): return 0<=x<w and 0<=y<h
    directions = [(-1,0),(1,0),(0,-1),(0,1)]
    for dx,dy in directions:
        nx, ny = px+dx, py+dy
        if in_bounds(nx,ny) and (nx,ny) not in obstacles:
            for res in resources:
                if abs(res[0]-nx)+abs(res[1]-ny)==0:
                    return [dx,dy]
    min_dist = float('inf')
    move = (0,0)
    for dx,dy in directions:
        nx, ny = px+dx, py+dy
        if in_bounds(nx,ny) and (nx,ny) not in obstacles:
            for res in resources:
                dist = abs(res[0]-nx)+abs(res[1]-ny)
                if dist<min_dist:
                    min_dist = dist
                    move = (dx,dy)
    return list(move)
